              Out of Stock
            </span>
          </div>
        )}
      </Link>

      {/* Product Body */}
      <div className="p-5 flex-col flex flex-1 justify-between">
        <div>
          <Link to={`/product/${product.id}`} className="hover:text-indigo-600 transition-colors">
