import React, { useEffect, useState, useRef } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useCart } from '../context/CartContext';
import { Star, ArrowLeft, Camera, Loader2, CheckCircle, ShoppingCart } from 'lucide-react';

interface Review {
  id: number;
  product_id: number;
  user_id: string;
  rating: number;
  comment: string;
  image_data: string | null;
  status: string;
  created_at: string;
}

interface ProductDetail {
  id: number;
  name: string;
  image_url: string;
  description: string;
  price: number;
  is_available: boolean;
  average_rating: number | null;
}

export const ProductDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { isAuthenticated, sessionToken, accountIdentifier } = useAuth();
  const { addToCart } = useCart();

  const [product, setProduct] = useState<ProductDetail | null>(null);
  const [reviews, setReviews] = useState<Review[]>([]);
  const [loading, setLoading] = useState(true);
  const [reviewsLoading, setReviewsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Form State
  const [rating, setRating] = useState(5);
  const [comment, setComment] = useState('');
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imageBase64, setImageBase64] = useState<string | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [addedFeedback, setAddedFeedback] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const fetchProductAndReviews = async () => {
    setLoading(true);
    setReviewsLoading(true);
    setError(null);
    try {
      // 1. Fetch Product details
      const prodRes = await fetch(`http://127.0.0.1:8000/api/products/${id}`);
      if (!prodRes.ok) {
        if (prodRes.status === 404) {
          throw new Error('Product not found.');
        }
        throw new Error('Failed to load product details.');
      }
      const prodData = await prodRes.json();
      setProduct(prodData);
      setLoading(false);

      // 2. Fetch approved reviews
      const revRes = await fetch(`http://127.0.0.1:8000/api/products/${id}/reviews`);
      if (revRes.ok) {
        const revData = await revRes.json();
        setReviews(revData);
      }
    } catch (err: any) {
      setError(err.message || 'An error occurred while fetching details.');
      setLoading(false);
    } finally {
      setReviewsLoading(false);
    }
  };

  useEffect(() => {
    if (id) {
      fetchProductAndReviews();
    }
  }, [id]);

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > 1024 * 1024) {
      setSubmitError('Image file is too large. Please select an image under 1MB.');
      return;
    }

    setImageFile(file);
    setSubmitError(null);

    // Create a local object URL for instant preview
    const objectUrl = URL.createObjectURL(file);
    setImagePreview(objectUrl);

    // Convert file to Base64
    const reader = new FileReader();
    reader.onloadend = () => {
      setImageBase64(reader.result as string);
    };
    reader.readAsDataURL(file);
  };

  const clearImage = () => {
    setImageFile(null);
    setImageBase64(null);
    setImagePreview(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const handleAddToCart = () => {
    if (!product || !product.is_available) return;
    addToCart({
      id: product.id,
      name: product.name,
      price: product.price,
      image_url: product.image_url,
      description: product.description,
      is_available: product.is_available,
    });
    setAddedFeedback(true);
    setTimeout(() => {
      setAddedFeedback(false);
    }, 1500);
  };

  const handleReviewSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!isAuthenticated) return;

    setSubmitting(true);
    setSubmitError(null);
    setSubmitSuccess(false);

    try {
      const response = await fetch(`http://127.0.0.1:8000/api/products/${id}/reviews`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${sessionToken}`,
        },
        body: JSON.stringify({
          rating,
          comment,
          image_data: imageBase64,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || 'Failed to submit review.');
      }

      setSubmitSuccess(true);
      setComment('');
      clearImage();
      setRating(5);
      // Let success notification show, reviews won't list the new review until approved anyway!
    } catch (err: any) {
      setSubmitError(err.message || 'Something went wrong. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  const renderStars = (count: number) => {
    return (
      <div className="flex gap-0.5">
        {[1, 2, 3, 4, 5].map((star) => (
          <Star
            key={star}
            className={`h-5 w-5 ${
              star <= count ? 'text-yellow-400 fill-yellow-400' : 'text-gray-300'
            }`}
