      // 1. Fetch Product details
      const prodRes = await fetch(`http://127.0.0.1:8000/api/products/${id}`);
      if (!prodRes.ok) {
        if (prodRes.status === 404) {
          throw new Error('Product not found.');
        }
        throw new Error('Failed to load product details.');
