    if (!isAuthenticated || accountIdentifier !== 'moderator') {
      navigate('/', { replace: true });
      return;
    }

    const fetchModerationData = async () => {
      setLoading(true);
      setError(null);
      try {
        // Fetch products first to display names instead of IDs
        const prodRes = await fetch('http://127.0.0.1:8000/api/products');
        let prodMap: Record<number, string> = {};
        if (prodRes.ok) {
          const products: Product[] = await prodRes.json();
          products.forEach((p) => {
            prodMap[p.id] = p.name;
          });
          setProductsMap(prodMap);
        }

        // Fetch pending reviews
        const revRes = await fetch('http://127.0.0.1:8000/api/moderation/reviews', {
          headers: {
            'Authorization': `Bearer ${sessionToken}`,
          },
